INSERT INTO `faqs` (`id`, `keywords`, `question`, `answer`) VALUES
(1, '320.000đ Nai bảo hành hỗ ship thoại trả trợ tư vấn Đồng điện đổi', 'Cho tôi lời khuyên chuyên sâu về phí giao hàng, đổi trả và bảo hành khi mua điện thoại.', 'Câu trả lời nên tập trung vào ba điểm: phí vận chuyển, thời gian giao hàng và quyền lợi đổi trả/bảo hành, để khách cảm thấy yên tâm.'),
(2, '200.000đ Nam Quảng bảo hành hỗ nghe ship tai trả trợ tư vấn đổi', 'Tôi muốn bạn trả lời như cố vấn dịch vụ khách hàng, giải thích rõ điều kiện miễn phí ship và bảo hành.', 'Nhận định đơn giản: miễn phí ship nếu đơn lớn, order trước giờ cut-off để giao nhanh, và giữ giấy tờ bảo hành để giải quyết sau này.'),
(3, '200.000đ Hà Nội bảo hành hỗ laptop ship trả trợ tư vấn đổi', 'Cung cấp cho tôi phương án xử lý khi khách hỏi về ship, trả hàng, thanh toán và bảo hành trong cùng một câu.', 'Câu trả lời nên tập trung vào ba điểm: phí vận chuyển, thời gian giao hàng và quyền lợi đổi trả/bảo hành, để khách cảm thấy yên tâm.'),
(4, '150.000đ Kon SSD Tum bảo cứng hành hỗ ship trả trợ tư vấn đổi ổ', 'Nếu không có dữ liệu trực tiếp, hãy đề xuất phương án bán hàng phù hợp cho đơn ổ cứng SSD 150.000đ.', 'Nhận định đơn giản: miễn phí ship nếu đơn lớn, order trước giờ cut-off để giao nhanh, và giữ giấy tờ bảo hành để giải quyết sau này.'),
(5, '320.000đ Phú Quốc bảo hành hỗ kỹ máy ship số thuật trả trợ tư vấn đổi ảnh', 'Nếu không có dữ liệu trực tiếp, hãy đề xuất phương án bán hàng phù hợp cho đơn máy ảnh kỹ thuật số 320.000đ.', 'Trường hợp chưa có dữ liệu cụ thể, bạn nên đưa ra giải pháp chung và hướng dẫn khách lục lại lịch sử chat hoặc yêu cầu bổ sung thông tin.'),
(6, '280.000đ Hà Nội bảo hành hồ hỗ minh ship thông trả trợ tư vấn đồng đổi', 'Tôi muốn câu trả lời có sắc thái hỗ trợ, đúng kiểu giải đáp vấn đề tổng quan yêu cầu.', 'Trường hợp chưa có dữ liệu cụ thể, bạn nên đưa ra giải pháp chung và hướng dẫn khách lục lại lịch sử chat hoặc yêu cầu bổ sung thông tin.'),
(7, '300.000đ Cần Thơ bảo hành hồ hỗ minh ship thông trả trợ tư vấn đồng đổi', 'Tôi muốn bạn nghĩ rộng và trả lời như chuyên viên hỗ trợ, dùng lịch sử chat để hiểu yêu cầu.', 'Hãy trả lời như một chuyên viên chăm sóc khách hàng, nhắc khách lưu giữ thông tin đơn hàng và nếu cần hỗ trợ thêm thì liên hệ ngay hotline.'),
(8, '220.000đ An Nghệ bảng bảo hành hỗ máy ship trả trợ tính tư vấn đổi', 'Cho tôi lời khuyên chuyên sâu về phí giao hàng, đổi trả và bảo hành khi mua máy tính bảng.', 'Hãy trả lời như một chuyên viên chăm sóc khách hàng, nhắc khách lưu giữ thông tin đơn hàng và nếu cần hỗ trợ thêm thì liên hệ ngay hotline.'),
(9, '500.000đ Hải Phòng bảo hành hỗ kỹ máy ship số thuật trả trợ tư vấn đổi ảnh', 'Làm ơn giải thích bằng tiếng Việt đơn giản và rõ ràng giống tư vấn viên, về phí ship và điều kiện đổi trả.', 'Nếu tôi ở vị trí tư vấn, tôi sẽ giải thích rằng phí ship dựa trên giá trị đơn và địa chỉ, rồi nhấn mạnh điều kiện miễn phí ship và cách liên hệ khi cần hỗ trợ đổi trả.'),
(10, '450.000đ Kon Tum bảo camera hành hỗ ship trình trả trợ tư vấn đổi', 'Bạn có thể đưa ra kịch bản phục vụ khách hàng khi họ thắc mắc phí vận chuyển và bảo hành camera hành trình?', 'Nhận định đơn giản: miễn phí ship nếu đơn lớn, order trước giờ cut-off để giao nhanh, và giữ giấy tờ bảo hành để giải quyết sau này.'),
(11, '1.200.000đ Chí Hồ Minh bảng bảo hành hỗ máy ship trả trợ tính tư vấn đổi', 'Nếu không có dữ liệu trực tiếp, hãy đề xuất phương án bán hàng phù hợp cho đơn máy tính bảng 1.200.000đ.', 'Câu trả lời nên tập trung vào ba điểm: phí vận chuyển, thời gian giao hàng và quyền lợi đổi trả/bảo hành, để khách cảm thấy yên tâm.'),
(12, '220.000đ Bình Dương bảng bảo hành hỗ máy ship trả trợ tính tư vấn đổi', 'Hãy tư vấn giúp tôi cách xử lý khi đơn máy tính bảng bị trễ giao và cần đổi địa chỉ.', 'Trường hợp chưa có dữ liệu cụ thể, bạn nên đưa ra giải pháp chung và hướng dẫn khách lục lại lịch sử chat hoặc yêu cầu bổ sung thông tin.'),
(13, '280.000đ Hóa Thanh bảo hành hỗ ship smartwatch trả trợ tư vấn đổi', 'Hãy tư vấn giúp tôi cách xử lý khi đơn smartwatch bị trễ giao và cần đổi địa chỉ.', 'Hãy trả lời như một chuyên viên chăm sóc khách hàng, nhắc khách lưu giữ thông tin đơn hàng và nếu cần hỗ trợ thêm thì liên hệ ngay hotline.'),
(14, '750.000đ Nha Trang bảo di hành hỗ loa ship trả trợ tư vấn đổi động', 'Cho tôi lời khuyên chuyên sâu về phí giao hàng, đổi trả và bảo hành khi mua loa di động.', 'Câu trả lời nên tập trung vào ba điểm: phí vận chuyển, thời gian giao hàng và quyền lợi đổi trả/bảo hành, để khách cảm thấy yên tâm.'),
(15, '180.000đ Bình bảo dự hành hỗ phòng pin ship trả trợ tư vấn Định đổi', 'Bạn có thể đưa ra kịch bản phục vụ khách hàng khi họ thắc mắc phí vận chuyển và bảo hành pin dự phòng?', 'Câu trả lời nên tập trung vào ba điểm: phí vận chuyển, thời gian giao hàng và quyền lợi đổi trả/bảo hành, để khách cảm thấy yên tâm.'),
(16, '350.000đ An Nghệ bảo bụi hành hút hỗ máy ship trả trợ tư vấn đổi', 'Tôi cần trợ giúp như một chuyên viên tư vấn: nên chọn phương án nào để ship máy hút bụi về Nghệ An tiết kiệm?', 'Nếu tôi ở vị trí tư vấn, tôi sẽ giải thích rằng phí ship dựa trên giá trị đơn và địa chỉ, rồi nhấn mạnh điều kiện miễn phí ship và cách liên hệ khi cần hỗ trợ đổi trả.'),
(17, '300.000đ Bình bảo chơi game hành hỗ máy ship trả trợ tư vấn Định đổi', 'Nếu không có dữ liệu trực tiếp, hãy đề xuất phương án bán hàng phù hợp cho đơn máy chơi game 300.000đ.', 'Trường hợp chưa có dữ liệu cụ thể, bạn nên đưa ra giải pháp chung và hướng dẫn khách lục lại lịch sử chat hoặc yêu cầu bổ sung thông tin.'),
(18, '800.000đ Phú Quốc bảo chơi game hành hỗ máy ship trả trợ tư vấn đổi', 'Hãy tư vấn giúp tôi cách xử lý khi đơn máy chơi game bị trễ giao và cần đổi địa chỉ.', 'Trường hợp chưa có dữ liệu cụ thể, bạn nên đưa ra giải pháp chung và hướng dẫn khách lục lại lịch sử chat hoặc yêu cầu bổ sung thông tin.'),
(19, '900.000đ An Nghệ bảo chiên dầu hành hỗ không nồi ship trả trợ tư vấn đổi', 'Cho tôi lời khuyên chuyên sâu về phí giao hàng, đổi trả và bảo hành khi mua nồi chiên không dầu.', 'Trường hợp chưa có dữ liệu cụ thể, bạn nên đưa ra giải pháp chung và hướng dẫn khách lục lại lịch sử chat hoặc yêu cầu bổ sung thông tin.'),
(20, '150.000đ Nam Quảng bảo hành hồ hỗ minh ship thông trả trợ tư vấn đồng đổi', 'Bạn có thể đưa ra kịch bản phục vụ khách hàng khi họ thắc mắc phí vận chuyển và bảo hành đồng hồ thông minh?', 'Nếu tôi ở vị trí tư vấn, tôi sẽ giải thích rằng phí ship dựa trên giá trị đơn và địa chỉ, rồi nhấn mạnh điều kiện miễn phí ship và cách liên hệ khi cần hỗ trợ đổi trả.'),
(21, '150.000đ Hà Nội chuyển giao hàng hỗ nhanh phí ship thoại trợ vận điện', 'Phí ship điện thoại về Hà Nội với giao nhanh là bao nhiêu?', 'Thông thường, đơn 150.000đ giao về Hà Nội sẽ có phí khoảng 20.000đ-60.000đ. Một số khu vực xa hơn phải mất phí cao hơn hoặc hỗ trợ miễn phí cho đơn lớn.'),
(22, '150.000đ Hà Nội chuyển chuẩn giao hàng hỗ phí ship thoại tiêu trợ vận điện', 'Phí ship điện thoại về Hà Nội với giao tiêu chuẩn là bao nhiêu?', 'Đối với điện thoại về Hà Nội, phí ship sẽ thay đổi tùy khu vực. Nếu đơn từ 500.000đ, cửa hàng thường hỗ trợ miễn phí hoặc giảm mạnh chi phí.'),
(23, '150.000đ Hà Nội chuyển giao hàng hỗ kiệm phí ship thoại tiết trợ vận điện', 'Phí ship điện thoại về Hà Nội với giao tiết kiệm là bao nhiêu?', 'Đối với điện thoại về Hà Nội, phí ship sẽ thay đổi tùy khu vực. Nếu đơn từ 500.000đ, cửa hàng thường hỗ trợ miễn phí hoặc giảm mạnh chi phí.'),
(24, '150.000đ Hà Nội chuyển giao hàng hỏa hỗ phí ship thoại trợ tốc vận điện', 'Phí ship điện thoại về Hà Nội với giao hỏa tốc là bao nhiêu?', 'Phí ship điện thoại về Hà Nội thường dao động theo khu vực và giá trị đơn. Với đơn 150.000đ, phí có thể từ 0 đến 120.000đ, một số quận nội thành có thể miễn phí.'),
(25, '150.000đ Hà Nội chuyển giao hàng hỗ ngày phí ship thoại trong trợ vận điện', 'Phí ship điện thoại về Hà Nội với giao trong ngày là bao nhiêu?', 'Đối với điện thoại về Hà Nội, phí ship sẽ thay đổi tùy khu vực. Nếu đơn từ 500.000đ, cửa hàng thường hỗ trợ miễn phí hoặc giảm mạnh chi phí.'),
(26, '150.000đ Hà Nội chuyển giao hàng hỗ nội phí ship thoại thành trợ vận điện', 'Phí ship điện thoại về Hà Nội với ship nội thành là bao nhiêu?', 'Cửa hàng tính phí ship điện thoại 150.000đ về Hà Nội căn bản trên tuyến đường và dịch vụ, thông thường không quá 100.000đ với ship nội thành.'),
(27, '150.000đ Hà Nội chuyển giao hàng hỗ ngoại phí ship thoại trợ tỉnh vận điện', 'Phí ship điện thoại về Hà Nội với ship ngoại tỉnh là bao nhiêu?', 'Bảng phí vận chuyển đến Hà Nội được tính theo trọng lượng và loại sản phẩm. Đơn 150.000đ điện thoại thường chỉ mất khoảng 30.000đ - 80.000đ nếu chọn ship ngoại tỉnh.'),
(28, '150.000đ Hà Nội chuyển giao hàng hỗ nhanh phí ship thoại trợ vận điện', 'Phí ship điện thoại về Hà Nội với vận chuyển nhanh là bao nhiêu?', 'Cửa hàng tính phí ship điện thoại 150.000đ về Hà Nội căn bản trên tuyến đường và dịch vụ, thông thường không quá 100.000đ với vận chuyển nhanh.'),
(29, '150.000đ Chí Hồ Minh chuyển giao hàng hỗ nhanh phí ship thoại trợ vận điện', 'Phí ship điện thoại về Hồ Chí Minh với giao nhanh là bao nhiêu?', 'Phí ship điện thoại về Hồ Chí Minh thường dao động theo khu vực và giá trị đơn. Với đơn 150.000đ, phí có thể từ 0 đến 120.000đ, một số quận nội thành có thể miễn phí.'),
(30, '150.000đ Chí Hồ Minh chuyển chuẩn giao hàng hỗ phí ship thoại tiêu trợ vận điện', 'Phí ship điện thoại về Hồ Chí Minh với giao tiêu chuẩn là bao nhiêu?', 'Đối với điện thoại về Hồ Chí Minh, phí ship sẽ thay đổi tùy khu vực. Nếu đơn từ 500.000đ, cửa hàng thường hỗ trợ miễn phí hoặc giảm mạnh chi phí.'),
